464: async function dispatch(ctx, dialog, message, state) {
465:   const key = dialog.task_id;
466:   if (!ctx.client?.session?.create || !ctx.client?.session?.prompt) {
467:     ctx.log("sdk_session_api_missing");
468:     return false;
469:   }
470:   // Save a durable claim BEFORE any potentially irreversible SDK call.
471:   // An ambiguous create/prompt failure is NEVER automatically retried.
472:   // PostgreSQL outbox claim is atomic with cancel/return-turn checks.
473:   // Never dispatch an already returned message.
474:   const lease = await ctx.cliCall({op:"claim", task_id:key, seq:message.seq,
475:                                    message_id:message.message_id});
476:   if (!lease?.claimed || !lease?.lease_token || !lease?.delivery_id) return false;
477:   state.inflight[key] = { seq: message.seq, message_id: message.message_id,
478:                          phase: "reserved", delivery_id: lease.delivery_id,
479:                          lease_token: lease.lease_token };
480:   saveState(ctx.paths, state);
481:   // Routing is deterministic: a durable binding for this dialogue always wins,
482:   // so the destination cannot drift when the owner switches chats or when the
483:   // app restarts and loads the plugin again. The live-chat lookup is only a
484:   // first-contact hint for a dialogue that has no binding yet; whatever it
485:   // resolves is persisted immediately and then stays authoritative.
486:   let sessionID = state.sessions[key];
487:   // Resolved below: null means "not known yet" and forces the fail-closed gate.
488:   let promptDirectory = null;
489:   if (typeof sessionID === "string" && sessionID) {
490:     if (ctx.log) ctx.log("route_durable_binding " + key + " session=" + sessionID);
491:   }
492:   // P35+: never adopt a pre-existing chat for a new dialogue. Adoption bound
493:   // bridge work to whatever chat happened to be newest in the plugin directory
494:   // (in practice the LinkedIn cron session in /home/kali), which the owner
495:   // cannot see in the sidebar. A dialogue without a durable binding always gets
496:   // its own dedicated, owner-visible session below.
497:   if (!sessionID) {
498:     delete state.sessions[key];
499:     state.inflight[key].phase = "create_attempted";
500:     saveState(ctx.paths, state);
501:     const created = await ctx.client.session.create({
502:       body: { title: "Bridge: " + (dialog.title || key.slice(0, 12)) },
503:       query: { directory: ctx.bridgeDirectory },
504:     });
505:     sessionID = created?.data?.id ?? created?.id;
506:     if (typeof sessionID !== "string" || !sessionID)
507:       throw new Error("sdk_session_create_unconfirmed");
508:     state.sessions[key] = sessionID;
509:     state.inflight[key].phase = "session_created";
510:     saveState(ctx.paths, state);
511:     // A session we just created is known to live in bridgeDirectory; that is
512:     // the only case where it is an acceptable prompt directory.
513:     promptDirectory = ctx.bridgeDirectory;
514:   }
515:   // The SDK's InstanceMiddleware resolves the workspace from `query.directory`
516:   // (query -> x-opencode-directory -> cwd) and seeds the whole request with it,
517:   // while the session itself is looked up by id alone. Prompting a session
518:   // whose directory cannot be resolved would therefore silently run the turn in
519:   // the wrong workspace. Fail closed instead: keep the durable reservation, log
520:   // a static category, and never retry automatically.
521:   if (promptDirectory === null) {
522:     const boundDirectory = ctx.sessionDirectory
523:       ? ctx.sessionDirectory(sessionID) : null;
524:     if (!boundDirectory) {
525:       if (ctx.log) ctx.log("route_session_directory_unknown " + key + " session=" + sessionID);
526:       return false;
527:     }
528:     promptDirectory = boundDirectory;
529:     if (ctx.log && boundDirectory !== ctx.directory)
530:       ctx.log("route_session_directory " + key + " using=" + boundDirectory);
531:   }
532:   state.inflight[key].phase = "prompt_attempted";
533:   saveState(ctx.paths, state);
534:   // The directory is a parameter, never captured: a recovery recreates the
535:   // session in a possibly different directory, and the retry must send the
536:   // prompt into the same directory the session was just created in.
537:   // The prompt is bounded: it runs while the cross-instance tick lock is held,
538:   // and a prompt that never settles used to keep that lock forever, stalling
539:   // every other dialogue. A timeout leaves the durable reservation in place
540:   // (never auto-retried) instead of blocking the whole bridge indefinitely.
541:   const send = (directory) => {
542:     const request = ctx.client.session.prompt({
543:       path: { id: sessionID }, query: { directory },
544:       body: { parts: [{ type: "text", text: buildPrompt(dialog, message) }] },
545:     });
546:     let timer;
547:     const timeout = new Promise((_, reject) => {
548:       timer = setTimeout(() => reject(new Error("sdk_prompt_timeout")), PROMPT_TIMEOUT_MS);
549:       if (typeof timer?.unref === "function") timer.unref();
550:     });
551:     return Promise.race([request, timeout]).finally(() => clearTimeout(timer));
552:   };
553:   try {
554:     await send(promptDirectory);
555:   } catch (e) {
556:     // The SDK has no reliable session.get in the plugin client, so recovery is
557:     // driven by the write itself: a CONFIRMED "not found" is deterministic and
558:     // safe to repair exactly once by creating a fresh session.
559:     if (!looksLikeMissingSession(e)) throw e;
560:     const probe = ctx.sessionExists ? ctx.sessionExists(sessionID) : sessionExistsInDb(sessionID);
561:     if (probe !== false) {
562:       // Not confirmed as deleted (or unknown): stay fail-closed, keep inflight.
563:       ctx.log("session_recovery_unconfirmed " + key + " exists=" + String(probe));
564:       throw e;
565:     }
566:     delete state.sessions[key];
567:     saveState(ctx.paths, state);
568:     ctx.log("session_missing_recreated " + key);
569:     state.inflight[key].phase = "create_attempted";
570:     saveState(ctx.paths, state);
571:     // A replacement session is created in the plugin's own directory, so the
572:     // prompt that follows must use exactly that directory too. Anything else
573:     // would resolve the request workspace to a directory the session does not
574:     // live in — the failure mode this gate exists to prevent.
575:     const recoveryDirectory = ctx.bridgeDirectory;
576:     const created = await ctx.client.session.create({
577:       body: { title: "Bridge: " + (dialog.title || key.slice(0, 12)) },
578:       query: { directory: recoveryDirectory },
579:     });
580:     sessionID = created?.data?.id ?? created?.id;
581:     if (typeof sessionID !== "string" || !sessionID)
582:       throw new Error("sdk_session_create_unconfirmed");
583:     state.sessions[key] = sessionID;
584:     state.inflight[key].phase = "session_created";
585:     saveState(ctx.paths, state);
586:     state.inflight[key].phase = "prompt_attempted";
587:     saveState(ctx.paths, state);
588:     await send(recoveryDirectory);
589:   }
590:   // No 'seen' receipt until PostgreSQL confirms this specific lease.
591:   const acked = await ctx.cliCall({op:"ack",delivery_id:lease.delivery_id,
592:                                   lease_token:lease.lease_token});
593:   if (!acked?.acked) throw new Error("pg_ack_unconfirmed");
594:   state.seen[key] = message.seq;
595:   delete state.inflight[key];
596:   saveState(ctx.paths, state);
597:   ctx.log("delivered " + key + " seq=" + message.seq + " to one MT session");
598:   return true;
599: }

619: async function reconcileAnsweredInflight(ctx, state, dialog) {
620:   const taskId = dialog.task_id, reserved = state.inflight[taskId];
621:   if (!reserved) return false;
622:   const now = Date.now();
623:   if (Number.isSafeInteger(reserved.reconcile_checked_ms) &&
624:       reserved.reconcile_checked_ms <= now &&
625:       reserved.reconcile_checked_ms > now - INFLIGHT_RECONCILE_MS) return false;
626: 
627:   // The cross-process lock in runTick protects this durable state update.
628:   // Throttling bounds GitHub API consumption while SDK outcome is unknown.
629:   reserved.reconcile_checked_ms = now;
630:   saveState(ctx.paths, state);
631:   let snapshot;
632:   try {
633:     snapshot = await ctx.cliCall({ op: "view", task_id: taskId,
634:                                   offset: 0, limit: 100, order: "newest" });
635:   } catch {
636:     ctx.log("inflight_reconcile_read_unavailable " + taskId);
637:     return false;
638:   }
639:   if (!confirmedMtResponseAfter(snapshot, taskId, reserved)) return false;
640: 
641:   // A confirmed response proves SDK completion, NOT outbox acknowledgement.
642:   // Keep the durable reservation until PostgreSQL has confirmed this lease.
643:   // Missing lease information is an ambiguous delivery: NEVER replay SDK.
644:   if (!Number.isSafeInteger(reserved.delivery_id) || reserved.delivery_id <= 0 ||
645:       typeof reserved.lease_token !== "string" ||
646:       !/^[0-9a-fA-F-]{36}$/.test(reserved.lease_token)) {
647:     ctx.log("inflight_reconcile_missing_lease_receipt " + taskId);
648:     return false;
649:   }
650:   let acked;
651:   try {
652:     acked = await ctx.cliCall({op:"ack", delivery_id:reserved.delivery_id,
653:                                lease_token:reserved.lease_token});
654:   } catch {
655:     // Including a lost response after a DB-committed ACK: the actor CLI
656:     // treats already-delivered status for the SAME delivery_id as success.
657:     ctx.log("inflight_reconcile_ack_outcome_unconfirmed " + taskId);
658:     return false;
659:   }
660:   if (acked?.acked !== true) {
661:     ctx.log("inflight_reconcile_ack_not_confirmed " + taskId);
662:     return false;
663:   }
664:   // Only after positive, identity-bound DB receipt may the SDK reservation
665:   // be cleared. This path NEVER invokes session.prompt or dispatch.
666:   state.seen[taskId] = Math.max(state.seen[taskId] || 0, reserved.seq);
667:   delete state.inflight[taskId];
668:   saveState(ctx.paths, state);
669:   ctx.log("inflight_reconciled_ack_confirmed " + taskId +
670:           " seq=" + reserved.seq);
671:   return true;
672: }

674: export async function runTick(ctx) {
675:   const holder = acquireLock(ctx.paths, ctx.log);
676:   if (!holder) return { status: "locked" };
677:   try {
678:     // IMPORTANT: read state ONLY AFTER acquiring exclusive cross-instance lock.
679:     const state = loadState(ctx.paths);
680:     const dialogs = await listAll(ctx.cliCall);
681:     // Auto-clear reservations whose dialogue the owner deleted: a tombstoned
682:     // or vanished dialogue can never be dispatched again, so its inflight
683:     // record is stale by definition and must not block future ticks.
684:     const lifecycle = new Map();
685:     for (const d of dialogs) if (d && d.task_id) lifecycle.set(d.task_id, d.lifecycle || "active");
686:     let cleared = 0;
687:     for (const taskId of Object.keys(state.inflight)) {
688:       // A dry-run may inspect and log, but must not acknowledge or clear
689:       // durable delivery records, including tombstoned reservations.
690:       if (ctx.dryRun) continue;
691:       const name = lifecycle.get(taskId);
692:       if (name === "active") continue;
693:       delete state.inflight[taskId];
694:       cleared++;
695:       ctx.log("inflight_cleared_deleted " + taskId + (name ? " (" + name + ")" : " (missing)"));
696:     }
697:     if (cleared) saveState(ctx.paths, state);
698:     let dispatched = 0, held = 0;
699:     for (const dialog of dialogs) {
700:       if (dispatched >= MAX_DISPATCH_PER_TICK) break;
701:       if (!dialog?.task_id || (dialog.lifecycle && dialog.lifecycle !== "active")) continue;
702:       // Allowlist gate: an excluded dialogue is not viewed, not reconciled and
703:       // not counted as held, so it costs no GitHub calls at all.
704:       if (ctx.taskIds && !ctx.taskIds.includes(dialog.task_id)) continue;
705:       if (state.inflight[dialog.task_id]) {
706:         if (!ctx.dryRun && await reconcileAnsweredInflight(ctx, state, dialog)) cleared++;
707:         else {
708:           held++;
709:           ctx.log("inflight_manual_reconciliation_required " + dialog.task_id);
710:           continue;
711:         }
712:       }
713:       let snapshot;
714:       try {
715:         snapshot = await ctx.cliCall({ op: "view", task_id: dialog.task_id,
716:                                       offset: 0, limit: 1, order: "newest" });
717:       } catch {
718:         ctx.log("dialog_view_failed " + dialog.task_id);
719:         continue;
720:       }
721:       const msg = latestPending(snapshot, state.seen[dialog.task_id] || 0);
722:       if (!msg) continue;
723:       let full;
724:       try {
725:         full = await ctx.cliCall({ op: "read", task_id: dialog.task_id,
726:                                    seq: msg.seq, message_id: msg.message_id });
727:         if (!full || full.seq !== msg.seq || full.message_id !== msg.message_id ||
728:             full.to !== "mt" || typeof full.body !== "string") {
729:           throw new Error("direct_git_message_mismatch");
730:         }
731:       } catch {
732:         ctx.log("direct_git_read_failed " + dialog.task_id);
733:         continue;
734:       }
735:       if (ctx.dryRun) {
736:         ctx.log("dry_run " + dialog.task_id + " seq=" + msg.seq);
737:         continue; // never acknowledge a message in dry-run
738:       }
739:       try {
740:         if (await dispatch(ctx, dialog, full, state)) dispatched++;
741:       } catch (e) {
742:         // Durable in-flight state stays written; no automatic replay.
743:         const kind = isSessionNotFound(e) ? "session_not_found" : "transient";
744:         let shape = "";
745:         try {
746:           // Static categories only: exception text may echo session ids,
747:           // request bodies or provider replies, so it never reaches the log.
748:           shape = JSON.stringify({
749:             name: String(e?.name || "").slice(0, 40),
750:             code: String(e?.code || "").slice(0, 40),
751:             status: e?.status ?? null,
752:           });
753:         } catch (_) { shape = "unserializable"; }
754:         ctx.log("dispatch_uncertain_manual_review " + dialog.task_id
755:                 + " seq=" + msg.seq + " (" + kind + ") " + shape);
756:       }
757:     }
758:     return { status: "ok", dispatched, held, cleared };
759:   } finally {
760:     releaseLock(ctx.paths, holder);
761:   }
762: }

601: function confirmedMtResponseAfter(snapshot, taskId, reserved) {
602:   // The local direct_git CLI validates the Git history; it returns last N
603:   // messages in ascending order, regardless of the unused "order" hint.
604:   if (snapshot?.task_id !== taskId || !/^[0-9a-f]{40}$/.test(snapshot?.head) ||
605:       !Number.isSafeInteger(snapshot?.seq) || snapshot.seq <= reserved.seq ||
606:       !Array.isArray(snapshot?.history) || snapshot.history.length > 100) return false;
607: 
608:   const sent = snapshot.history.find((m) =>
609:     m?.seq === reserved.seq && m.message_id === reserved.message_id &&
610:     m.from === "chatgpt" && m.to === "mt");
611:   const answered = snapshot.history.find((m) =>
612:     m?.seq === reserved.seq + 1 && m.from === "mt" && m.to === "chatgpt" &&
613:     ["report", "ack", "task", "close"].includes(m.kind));
614:   // No inference based on elapsed time, SDK status, a newer head alone, or
615:   // another unrelated MT answer. The exact immutable Git turn must be visible.
616:   return Boolean(sent && answered);
617: }
